#ifndef RR_RELAY_CATALOG_POLICY_H
#define RR_RELAY_CATALOG_POLICY_H
#include <glib.h>

/* The wire sync key is generated by g_uuid_string_random(). A directly
 * authenticated neighbor is not trusted to allocate unbounded state. */
static inline gboolean rr_catalog_sync_id_valid(const char *id) {
   return id && g_uuid_string_is_valid(id);
}

/* A peer may supersede its previous snapshot, but may never keep multiple
 * active receive sessions. Values remain owned/freed by the hash table. */
static inline guint rr_catalog_drop_origin(GHashTable *sessions, const char *origin, const char *(*owner_of)(gconstpointer)) {
   if (!sessions || !origin || !owner_of) {
      return 0;
   }
   guint removed = 0;
   GHashTableIter iter;
   gpointer key, value;
   g_hash_table_iter_init(&iter, sessions);
   while (g_hash_table_iter_next(&iter, &key, &value)) {
      if (!g_strcmp0(owner_of(value), origin)) {
         g_hash_table_iter_remove(&iter);
         removed++;
      }
   }
   return removed;
}
#endif
